<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1'><title>Create account</title><style>body{font:16px system-ui;background:#f3f6fb;display:grid;min-height:100vh;place-items:center}.card{background:white;padding:32px;border-radius:14px;width:min(420px,90vw)}.field{margin:16px 0}label{display:block}input{width:100%;padding:12px;box-sizing:border-box}.btn{padding:12px;background:#078565;color:white;border:0;border-radius:7px;width:100%}</style></head><body><div class='card'><h1>Create your workspace</h1><form method='post' action='{{ route('register') }}'>@csrf<div class='field'><label>Name</label><input name='name' required></div><div class='field'><label>Email</label><input type='email' name='email' required></div><div class='field'><label>Password</label><input type='password' name='password' minlength='10' required></div><div class='field'><label>Confirm password</label><input type='password' name='password_confirmation' required></div><button class='btn'>Create account</button></form></div></body></html>